/// GET /ips
/// C`loudflare/JD` Cloud IP Details
///
/// Returns `ClientRequestBuilder` for customization.
/// Use `get_ips_execute()` to send, or `get_ips` for simplest API.

pub fn get_ips_builder(
    client: &SimpleHttpClient,
    networks: &Option<String>,
) -> Result<ClientRequestBuilder<SystemDnsResolver>, ApiError> {
    // Build URL
    let endpoint_url = format!("https://api.cloudflare.com/client/v4/ips",);

    // Build request
    let mut query_parts = Vec::new();
    if let Some(val) = networks.as_ref() {
        query_parts.push(format!("networks={}", val));
    }

    let url_with_query = if query_parts.is_empty() {
        endpoint_url
    } else {
        format!("{}?{}", endpoint_url, query_parts.join("&"))
    };

    let builder = client
        .get(&url_with_query)
        .map_err(|e| ApiError::RequestBuildFailed(e.to_string()))?;

    Ok(builder)
}

